# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A simple (1+1)-Evolution Strategy with adaptive step-size control.
# Search state: Maintains a single current best candidate solution and its objective value, plus a standard deviation (sigma) for mutations.
# Candidate generation: New candidates are generated by adding Gaussian noise scaled by sigma to the current best solution.
# Selection and replacement: A greedy selection process; the new candidate replaces the current best if it improves the objective value.
# Adaptation: Employs the 1/5th success rule: sigma increases if the success rate is high and decreases if it is low to maintain optimal convergence.
# Exploration mechanisms: Initially global exploration via large sigma, refining as the solution converges.
# Exploitation mechanisms: Local hill-climbing via the adaptive Gaussian perturbation.
# Boundary handling: Candidates are clipped to the provided lower and upper bounds.
# Budget strategy: A strict while loop runs until the evaluation count reaches the provided budget.
# Closest known influences: The (1+1)-ES as popularized by Rechenberg and Schwefel.
# Novelty or unusual aspects: Minimal implementation without external dependencies, self-tuning step size.
# Failure modes: Susceptible to local optima; does not handle non-convex landscapes with very sharp basin barriers effectively.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'lower'):
            lb, ub = func.lower, func.upper
        else:
            lb, ub = func.bounds.lb, func.bounds.ub
        
        lb = np.array(lb)
        ub = np.array(ub)
        
        # Initialize
        x = np.random.uniform(lb, ub, self.dim)
        y = func(x)
        
        # Initial sigma as a fraction of domain width
        sigma = 0.2 * (ub - lb)
        
        best_x = np.copy(x)
        best_y = y
        
        evals = 1
        success_count = 0
        
        while evals < self.budget:
            # Generate mutation
            noise = np.random.normal(0, sigma, self.dim)
            x_new = np.clip(x + noise, lb, ub)
            
            y_new = func(x_new)
            evals += 1
            
            # Selection
            if y_new <= y:
                x = np.copy(x_new)
                y = y_new
                success_count += 1
                if y < best_y:
                    best_x = np.copy(x)
                    best_y = y
            
            # 1/5th success rule for step size adaptation
            # Periodically adjust sigma to keep success rate near 20%
            if evals % (10 + self.dim) == 0:
                success_rate = success_count / (10 + self.dim)
                if success_rate > 0.2:
                    sigma *= 1.2
                elif success_rate < 0.2:
                    sigma /= 1.2
                success_count = 0
                
        return best_x, best_y
